# AMP cluster wrapper: ClusterServer plus one ShardsServer per <Region> in ClusterConfig.xml.
# A region that dies makes the cluster panic and exit, so the whole set ends together and AMP restarts it.
Set-Location $PSScriptRoot
$srv = Join-Path $PSScriptRoot '..\3976640\server'
$regions = @(([xml](Get-Content -Raw ClusterConfig.xml)).ClusterConfig.Region | ForEach-Object { $_.Address })
function Start-Shard($exe, $arg) {
    $p = @{ FilePath = (Join-Path $srv $exe); WorkingDirectory = $PSScriptRoot; NoNewWindow = $true; PassThru = $true }
    if ($arg) { $p.ArgumentList = $arg }
    Start-Process @p
}
Remove-Item amp-stop.flag, tmp\luaexec\amp-stop.request -ErrorAction SilentlyContinue
$cluster = Start-Shard 'ClusterServer.exe'
Start-Sleep 3
$shards = @(foreach ($r in $regions) { Start-Shard 'ShardsServer.exe' $r })
$stopping = $false
while (-not $cluster.HasExited) {
    if (-not $stopping -and (Test-Path amp-stop.flag)) {
        $stopping = $true
        Remove-Item amp-stop.flag -ErrorAction SilentlyContinue
        New-Item -ItemType Directory -Force tmp\luaexec | Out-Null
        [IO.File]::WriteAllText("$PSScriptRoot\tmp\amp-stop.lua", 'ShutdownServer()')
        [IO.File]::WriteAllText("$PSScriptRoot\tmp\luaexec\amp-stop.request", '{"requestId":"amp-stop","luaFilePath":"tmp/amp-stop.lua"}')
        Write-Output '[AMP] Stop requested, saving cluster'
    }
    Start-Sleep 1
}
foreach ($p in $shards) { if (-not $p.WaitForExit(60000)) { $p.Kill() } }
